{"content":"use std::fmt;

/// Represents a complex number with real and imaginary parts.
#[derive(Debug, Clone)]
pub struct FftComplex {
    pub real: f32,
    pub imag: f32,
}

impl FftComplex {
    /// Create a unit root for the given N (z^N = 1).
    pub fn unit_root(n: usize) -> Self {
        let angle = -2.0 * std::f32::consts::PI / n as f32;
        FftComplex {
            real: std::cos(angle),
            imag: std::sin(angle),
        }
    }

    /// Create the reciprocal of the unit root.
    pub fn reciprocal(self) -> Self {
        FftComplex {
            real: 1.0 / (self.real * self.real + self.imag * self.imag),
            imag: -2.0 * self.real * self.imag / (self.real * self.real + self.imag * self.imag),
        }
    }

    /// Add two complex numbers.
    pub fn add(self, other: Self) -> Self {
        FftComplex {
            real: self.real + other.real,
            imag: self.imag + other.imag,
        }
    }

    /// Subtract two complex numbers.
    pub fn sub(self, other: Self) -> Self {
        FftComplex {
            real: self.real - other.real,
            imag: self.imag - other.imag,
        }
    }

    /// Multiply two complex numbers.
    pub fn mul(self, other: Self) -> Self {
        FftComplex {
            real: self.real * other.real - self.imag * other.imag,
            imag: self.real * other.imag + self.imag * other.real,
        }
    }

    /// Self-inverse (conjugate divided by magnitude squared).
    pub fn selfmul(self, unit: Self) -> Self {
        let mag_sq = self.real * self.real + self.imag * self.imag;
        if mag_sq.is_zero() {
            return FftComplex { real: 1.0, imag: 0.0 };
        }
        let scale = 1.0 / mag_sq;
        FftComplex {
            real: (self.real * unit.real - self.imag * unit.imag) * scale,
            imag: (self.real * unit.imag + self.imag * unit.real) * scale,
        }
    }

    /// Copy self into target.
    pub fn copy_into(self, target: &mut Self) {
        target.real = self.real;
        target.imag = self.imag;
    }

    /// Swap two complex numbers.
    pub fn swap(a: &mut Self, b: &mut Self) {
        let tmp = *a;
        *a = *b;
        *b = tmp;
    }
}

impl Default for FftComplex {
    fn default() -> Self {
        FftComplex { real: 0.0, imag: 0.0 }
    }
}

impl fmt::Display for FftComplex {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "({:.4}, {:.4})", self.real, self.imag)
    }
}
