{"content":"use std::fmt;

/// Represents a power-of-two size of the FFT (log2(N)).
#[derive(Debug, Clone)]
pub struct FftSize {
    pub logsize: usize,
}

impl FftSize {
    /// Create a FftSize from a power-of-two size.
    pub fn new(size: usize) -> Self {
        assert!(size.is_power_of_two(), "Size must be a power of two");
        let logsize = size.to_log2();
        Self { logsize }
    }

    /// Get the size (must be power of two).
    pub fn size(&self) -> usize {
        (1 << self.logsize) as usize
    }

    /// Get the log2 of the size.
    pub fn log2(&self) -> usize {
        self.logsize
    }
}

impl FftSize {
    /// Check if this is a valid power-of-two size.
    pub fn is_valid(&self) -> bool {
        self.size() > 0
    }
}

impl std::fmt::Display for FftSize {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.size())
    }
}

impl std::str::FromStr for FftSize {
    type Err = ();

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        let n: usize = s.parse().map_err(|_| ())?
            .then(|| {
                let size = (1 << s.to_string().len()) as usize;
                Ok(FftSize { logsize: s.to_string().len() })
            })?;
        Ok(FftSize { logsize: n.to_log2() })
    }
}

impl std::ops::Add for FftSize {
    type Output = FftSize;

    fn add(self, other: Self) -> Self::Output {
        assert!(self.is_valid() && other.is_valid(), "Both sizes must be valid power-of-two sizes");
        let max_log = self.log2().max(other.log2());
        let size = (1 << max_log) as usize;
        FftSize::new(size)
    }
}

impl std::ops::Mul for FftSize {
    type Output = FftSize;

    fn mul(self, other: Self) -> Self::Output {
        assert!(self.is_valid() && other.is_valid(), "Both sizes must be valid power-of-two sizes");
        let max_log = self.log2().max(other.log2());
        let size = (1 << max_log) as usize;
        FftSize::new(size)
    }
}

impl std::ops::Sub for FftSize {
    type Output = FftSize;

    fn sub(self, other: Self) -> Self::Output {
        assert!(self.is_valid() && other.is_valid(), "Both sizes must be valid power-of-two sizes");
        let min_log = self.log2().min(other.log2());
        let size = (1 << min_log) as usize;
        FftSize::new(size)
    }
}

impl std::ops::AddAssign for FftSize {
    fn add_assign(&mut self, other: Self) {
        assert!(self.is_valid() && other.is_valid(), "Both sizes must be valid power-of-two sizes");
        let max_log = self.log2().max(other.log2());
        let size = (1 << max_log) as usize;
        self.logsize = max_log;
    }
}

impl std::ops::SubAssign for FftSize {
    fn sub_assign(&mut self, other: Self) {
        assert!(self.is_valid() && other.is_valid(), "Both sizes must be valid power-of-two sizes");
        let min_log = self.log2().min(other.log2());
